import math


def fixed_chain(task, tools):
    if 'query' in task:
        return str(tools['search_notes'](task['query'], 1)[0])
    closes = [tools['get_close'](task['ticker'], d) for d in task['dates']]
    if len(closes) == 1:
        return f'{closes[0]:.2f}'
    return f"{tools['pct_change'](closes[0], closes[1]):.2f}%"


def chain_scorecard(tasks, tools):
    right = [fixed_chain(t, tools) == t['answer'] for t in tasks]
    p = sum(right) / len(right)
    return {'solved': sum(right), 'rate': p, 'se': math.sqrt(p * (1 - p) / len(right))}

